+/// Iterator over certificates from a PEM reader.
+#[cfg(feature = "std")]
+pub struct Certs<'a> {
+    rd: &'a mut dyn io::BufRead,
+}
+
+#[cfg(feature = "std")]
+impl Iterator for Certs<'_> {
+    type Item = Result<CertificateDer<'static>, io::Error>;
+
+    fn next(&mut self) -> Option<Self::Item> {
+        loop {
+            match read_one(self.rd).transpose() {
+                Some(Ok(Item::X509Certificate(cert))) => return Some(Ok(cert)),
+                Some(Err(err)) => return Some(Err(err)),
+                Some(Ok(_)) => continue,
+                None => return None,
+            }
+        }
+    }
